package steps

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

//truebdd:concept given "installation"
func concept08bdc8ba20fbc17f8cbea598ca6da5bdbc121817e637f18277eb83c75896fcf3(state *State, args []string) error {
	// The declared CLI says the calculator is built with go build from
	// ./services/calc at the host root; the binding says the built program
	// lives under the host's tmp directory and its path is kept for the When.
	const (
		servicePackage = "./services/calc"
		programName    = "calc"
		tmpDirName     = "tmp"
		buildPrefix    = "calc-install-"
	)

	workDir, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("the calculator is installed: working directory: %w", err)
	}

	// The suite runs from its own package directory, so find the host root by
	// walking up to the directory that holds go.mod.
	hostRoot := ""
	for dir := workDir; ; {
		if _, statErr := os.Stat(filepath.Join(dir, "go.mod")); statErr == nil {
			hostRoot = dir
			break
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return fmt.Errorf("the calculator is installed: no host root with go.mod at or above %s", workDir)
		}
		dir = parent
	}

	tmpRoot := filepath.Join(hostRoot, tmpDirName)
	if err := os.MkdirAll(tmpRoot, 0o755); err != nil {
		return fmt.Errorf("the calculator is installed: host tmp directory %s: %w", tmpRoot, err)
	}

	buildDir, err := os.MkdirTemp(tmpRoot, buildPrefix)
	if err != nil {
		return fmt.Errorf("the calculator is installed: build directory under %s: %w", tmpRoot, err)
	}

	program := filepath.Join(buildDir, programName)
	build := exec.Command("go", "build", "-o", program, servicePackage)
	build.Dir = hostRoot
	if output, err := build.CombinedOutput(); err != nil {
		return fmt.Errorf("the calculator is installed: go build -o %s %s in %s: %w: %s", program, servicePackage, hostRoot, err, output)
	}

	if _, err := os.Stat(program); err != nil {
		return fmt.Errorf("the calculator is installed: built program %s: %w", program, err)
	}

	state.Program = program
	state.HostRoot = hostRoot

	return nil
}

package steps

import (
	"errors"
	"fmt"
	"os/exec"
	"strconv"
	"strings"
)

//truebdd:concept when "doubling"
func concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b(state *State, args []string) error {
	// The declared CLI says the calculator program is run from the host root as
	// "calc double VALUE" and prints the doubled integer and a newline on
	// stdout; the binding says this When runs that command as a process with
	// the step's whole number and keeps its integer stdout.
	const (
		commandName = "double"
		stepLabel   = "the Owner doubles"
	)

	if len(args) != 1 {
		return fmt.Errorf("%s: expected 1 capture (the whole number), got %d", stepLabel, len(args))
	}
	value := args[0]

	if state.Program == "" {
		return fmt.Errorf("%s %s: no calculator program kept; the installation Given must run first", stepLabel, value)
	}
	if state.HostRoot == "" {
		return fmt.Errorf("%s %s: no host root kept; the installation Given must run first", stepLabel, value)
	}

	state.Result = 0
	state.ResultSet = false

	run := exec.Command(state.Program, commandName, value)
	run.Dir = state.HostRoot
	stdout, err := run.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return fmt.Errorf("%s %s: %s %s %s in %s: %w: %s", stepLabel, value, state.Program, commandName, value, state.HostRoot, err, strings.TrimSpace(string(exitErr.Stderr)))
		}
		return fmt.Errorf("%s %s: %s %s %s in %s: %w", stepLabel, value, state.Program, commandName, value, state.HostRoot, err)
	}

	printed := strings.TrimSpace(string(stdout))
	doubled, err := strconv.Atoi(printed)
	if err != nil {
		return fmt.Errorf("%s %s: stdout %q of %s %s %s is not an integer: %w", stepLabel, value, printed, state.Program, commandName, value, err)
	}

	state.Result = doubled
	state.ResultSet = true

	return nil
}

package steps

import (
	"fmt"
	"strconv"
)

//truebdd:concept then "result"
func concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e(state *State, args []string) error {
	// The binding says this Then compares the kept stdout of the declared
	// double command with the step's expected whole number. The doubling When
	// already ran that command as a process and kept its integer stdout, so
	// this step only reads the capture and observes what was kept; it never
	// doubles anything itself.
	const stepLabel = "the result is"

	if len(args) != 1 {
		return fmt.Errorf("%s: expected 1 capture (the expected whole number), got %d", stepLabel, len(args))
	}
	written := args[0]

	expected, err := strconv.Atoi(written)
	if err != nil {
		return fmt.Errorf("%s %s: the expected whole number %q is not an integer: %w", stepLabel, written, written, err)
	}

	if !state.ResultSet {
		return fmt.Errorf("%s %s: no double command stdout kept; the doubling When must run first", stepLabel, written)
	}

	if state.Result != expected {
		return fmt.Errorf("%s %s: the double command printed %d, not %d", stepLabel, written, state.Result, expected)
	}

	return nil
}

package steps

func Register(suite interface {
	Step(string, func(*State, []string) error)
}) {
	suite.Step("^the calculator is installed$", concept08bdc8ba20fbc17f8cbea598ca6da5bdbc121817e637f18277eb83c75896fcf3)

	suite.Step("^the Owner doubles (-?\\d+)$", concept49c5ece16061081405dd19dacacf9182109378be8a0f1d472e9711fff19b790b)

	suite.Step("^the result is (-?\\d+)$", concepted1de9371d2a7b37ce77d82464ab6737cf25f6c86f592518873001398dd1313e)
}

package steps

type State struct {
	// Program is the filesystem path of the calculator program built by the
	// installation Given, kept for the When that runs it.
	Program string

	// HostRoot is the host's root directory (the one holding go.mod and
	// services/calc), the directory the declared interface says the command is
	// run from.
	HostRoot string

	// Result is the integer the calculator's double command printed on stdout,
	// kept by the doubling When for the Then that observes it.
	Result int

	// ResultSet reports whether a doubling When has run the double command and
	// kept its integer stdout in Result.
	ResultSet bool
}
